//! Unicode 15.1.0 property and simple case tables (doc 02 3.3).
//!
//! `tables.rs` is generated by `examples/gen_unicode.rs` from `xtask/data/ucd-15.1.0`; it is
//! never edited by hand. The lookup code below is the only consumer and stays small.

pub mod tables;

/// The Unicode version the tables were generated from.
pub const UNICODE_VERSION: (u8, u8, u8) = (15, 1, 0);
/// The exact size of the generated statics; enforced by the generator (`<= 48 KiB`).
pub const TABLE_BYTES: usize = tables::TABLE_BYTES;

const ALPHA: u8 = 1;
const PUNCT: u8 = 2;
const WIDE: u8 = 4;
const ZERO: u8 = 8;

fn props(c: u32) -> u8 {
    if c > 0x10ffff {
        return 0;
    }
    let block = tables::PROPS_STAGE1
        .get((c >> 8) as usize)
        .copied()
        .unwrap_or(0) as usize;
    let index = block
        .wrapping_mul(128)
        .wrapping_add(((c & 255) >> 1) as usize);
    let packed = tables::PROPS_STAGE2.get(index).copied().unwrap_or(0);
    (packed >> (4usize.wrapping_mul((c & 1) as usize))) & 0xf
}

/// DerivedCoreProperties `Alphabetic`, plus non-ASCII `Nd`.
#[must_use]
pub fn is_alpha(c: u32) -> bool {
    props(c) & ALPHA != 0
}

/// `P*`/`S*` categories, non-alphabetic marks and the three no-break spaces.
#[must_use]
pub fn is_punct(c: u32) -> bool {
    props(c) & PUNCT != 0
}

/// `0` for zero-width code points, `2` for East_Asian_Width `W`/`F`, else `1`.
#[must_use]
pub fn width_bits(c: u32) -> u8 {
    let bits = props(c);
    if bits & ZERO != 0 {
        0
    } else if bits & WIDE != 0 {
        2
    } else {
        1
    }
}

fn case_pair(c: u32) -> (i32, i32) {
    if c >= 0x20000 {
        return (0, 0);
    }
    let block = tables::CASE_STAGE1
        .get((c >> 8) as usize)
        .copied()
        .unwrap_or(0) as usize;
    let index = block.wrapping_mul(256).wrapping_add((c & 255) as usize);
    let pair = tables::CASE_STAGE2.get(index).copied().unwrap_or(0) as usize;
    tables::CASE_PAIRS.get(pair).copied().unwrap_or((0, 0))
}

/// Simple uppercase mapping (UnicodeData fields 12, no SpecialCasing).
#[must_use]
pub fn simple_upper(c: u32) -> u32 {
    let (upper, _) = case_pair(c);
    c.wrapping_add(upper as u32)
}

/// Simple lowercase mapping (UnicodeData fields 13, no SpecialCasing).
#[must_use]
pub fn simple_lower(c: u32) -> u32 {
    let (_, lower) = case_pair(c);
    c.wrapping_add(lower as u32)
}

